WITH filtered_subscriptions AS (SELECT * FROM subscriptions WHERE end_date < '2024-01-01'), subscriptions_stats AS (SELECT CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END AS end_cohort, COUNT(CASE WHEN status = 'ACTIVE' THEN 1 END) AS active_count FROM filtered_subscriptions GROUP BY CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT end_cohort, active_count FROM subscriptions_stats
